export type PaymentView = 'success' | 'processing' | 'failed' | 'cancelled' | 'error';

export const normalizePaymentView = (value: string | null | undefined): PaymentView | null => {
  switch (value?.toLowerCase()) {
    case 'success':
    case 'succeeded':
    case 'paid':
      return 'success';
    case 'processing':
    case 'pending':
      return 'processing';
    case 'failed':
    case 'payment_failed':
      return 'failed';
    case 'cancelled':
    case 'canceled':
    case 'abandoned':
    case 'incomplete':
      return 'cancelled';
    case 'error':
      return 'error';
    default:
      return null;
  }
};

export const initialPaymentView = (
  explicitStatus: string | null,
  redirectStatus: string | null,
  hasProviderSession: boolean,
): PaymentView => {
  if (hasProviderSession) return 'processing';
  const normalized = normalizePaymentView(explicitStatus);
  if (normalized) return normalized;
  if (redirectStatus === 'succeeded') return 'success';
  if (redirectStatus === 'processing') return 'processing';
  if (redirectStatus === 'failed') return 'cancelled';
  return 'error';
};
